    "</style></head><body>\n"
    "<header><div class=\"top\"><svg class=\"logo\" viewBox=\"0 0 32 32\" aria-hidden=\"true\"><defs><clipPath id=\"lc\"><rect x=\"1.25\" y=\"1.25\" width=\"29.5\" height=\"29.5\" rx=\"7\"/></clipPath><filter id=\"lb\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feGaussianBlur stdDeviation=\"4.2\"/></filter><filter id=\"lr\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feGaussianBlur stdDeviation=\"1.1\"/></filter><pattern id=\"lp\" width=\"1.9\" height=\"32\" patternUnits=\"userSpaceOnUse\"><rect width=\".8\" height=\"32\" fill=\"#fff\" fill-opacity=\".14\"/></pattern><linearGradient id=\"lf\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\".25\" stop-color=\"#fff\"/><stop offset=\".8\" stop-color=\"#fff\" stop-opacity=\"0\"/></linearGradient><mask id=\"lm\"><rect width=\"32\" height=\"32\" fill=\"url(#lf)\"/></mask></defs><g clip-path=\"url(#lc)\"><rect width=\"32\" height=\"32\" fill=\"#963d97\"/><g filter=\"url(#lb)\"><circle cx=\"4\" cy=\"4\" r=\"9\" fill=\"#61bb46\"/><circle cx=\"20\" cy=\"2\" r=\"8\" fill=\"#fdb827\"/><circle cx=\"31\" cy=\"12\" r=\"8\" fill=\"#f5821f\"/><circle cx=\"26\" cy=\"27\" r=\"9\" fill=\"#e03a3e\"/><circle cx=\"10\" cy=\"31\" r=\"9\" fill=\"#963d97\"/><circle cx=\"1\" cy=\"18\" r=\"8\" fill=\"#009ddc\"/></g><g mask=\"url(#lm)\"><path d=\"M-2 13 C5 7 10 12 16 9 S26 5 34 9 V15 C27 11.5 21 15.5 15 13 S5 12.5 -2 16Z\" fill=\"#fff\" fill-opacity=\".5\" filter=\"url(#lr)\"/><path d=\"M-2 13 C5 7 10 12 16 9 S26 5 34 9 V26 H-2Z\" fill=\"url(#lp)\"/></g></g><rect x=\"1.25\" y=\"1.25\" width=\"29.5\" height=\"29.5\" rx=\"7\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.2\"/></svg><div class=\"ttl\"><h1>Aurora68 Setup and Recovery</h1><div class=\"why\" id=\"why\">Connecting</div></div><div class=\"state\" id=\"hstate\">...</div></div>\n"
    "<div class=\"rainbow\"></div><nav id=\"nav\"><button style=\"--c:var(--g)\" data-t=\"ov\" class=\"on\">Overview</button><button style=\"--c:var(--y)\" data-t=\"fi\">Files</button><button style=\"--c:var(--o)\" data-t=\"wi\">WiFi</button><button style=\"--c:var(--r)\" data-t=\"op\">Options</button><button style=\"--c:repeating-linear-gradient(90deg,#000 0 1px,#fff 1px 2px)\" data-t=\"dg\">Diagnostics</button><button style=\"--c:var(--six)\" data-t=\"dp\">Display</button><button style=\"--c:var(--p)\" data-t=\"tx\">Text files</button><button style=\"--c:var(--b)\" data-t=\"lo\">Log</button></nav></header>\n"
    "<main>\n"
    "<section class=\"tab on\" id=\"ov\">\n"
    "<div class=\"card warn\" id=\"apc\" style=\"display:none\"><h2><span>Access point</span></h2><div class=\"grid\" id=\"apg\"></div><p class=\"mut\" id=\"apn\" style=\"margin-bottom:0\"></p></div>\n"
    "<div class=\"card warn\" id=\"rb\" style=\"display:none\"><h2><span>The last starts did not reach the Finder</span></h2><p class=\"mut\">The kernel before the current one is on the card as kernel8.old.</p>\n"
    "<button class=\"b p\" onclick=\"act('/r/rollback','Roll back to kernel8.old?')\">Roll back the kernel</button></div>\n"
    "<div class=\"card warn\" id=\"oncec\" style=\"display:none\"><h2><span>A one-shot debug start is armed</span></h2><p id=\"oncet\" style=\"margin:0 0 8px\"></p>\n"
    "<div class=\"row\"><button class=\"b p\" onclick=\"act('/r/reboot?how=normal','Restart the Pi normally? The next start uses the debug options once.')\">Restart normally to run it</button><button class=\"b\" onclick=\"oncecancel()\">Cancel it</button></div></div>\n"
    "<div class=\"card\"><h2><span>State</span></h2><div class=\"grid\" id=\"st\"></div><div id=\"notes\" class=\"mut\" style=\"margin-top:10px\"></div></div>\n"
    "<div class=\"card\"><h2><span>Restart</span></h2><p class=\"mut\">The Mac stays off while recovery runs. Restart normally to start it again.</p><div class=\"row\">\n"
    "<button class=\"b p\" onclick=\"act('/r/reboot?how=normal','Restart the Pi normally (the Mac starts)?')\">Restart normally</button>\n"
    "<button class=\"b\" onclick=\"act('/r/reboot?how=recovery','Restart into recovery?')\">Restart into recovery</button>\n"
    "<button class=\"b\" onclick=\"lock()\">Change PIN</button></div></div></section>\n"
    "<section class=\"tab\" id=\"fi\">\n"
    "<div class=\"card\"><h2><span>Upload</span></h2><p class=\"mut\">kernel8.img is checked before it replaces the old one (kept as kernel8.old). Every upload is read back from the card and compared.</p>\n"
    "<label>File<input type=\"file\" id=\"up\" onchange=\"el('upname').value=this.files[0]?this.files[0].name:''\"></label>\n"
    "<label>Save on the card as<input type=\"text\" id=\"upname\" placeholder=\"the file's own name\"></label>\n"
    "<div class=\"row\" style=\"margin-top:12px\"><button class=\"b p\" onclick=\"upload()\">Upload</button><span class=\"mut\" id=\"upst\"></span></div><div class=\"bar\"><i id=\"upbar\"></i></div></div>\n"
    "<div class=\"card\"><h2><span>Files on the SD card</span></h2><div class=\"mut\" id=\"card\"></div><ul class=\"fl\" id=\"files\"></ul></div></section>\n"
    "<section class=\"tab\" id=\"wi\"><div class=\"card\"><h2><span>WiFi</span></h2><div class=\"mut\" id=\"wset\"></div>\n"
    "<div class=\"row\" style=\"margin-top:10px\"><button class=\"b\" onclick=\"wscan()\">Scan for networks</button></div>\n"
    "<label>Network<select id=\"wlist\" onchange=\"if(this.value)el('wssid').value=this.value\"></select></label>\n"
    "<label>Name (SSID)<input type=\"text\" id=\"wssid\"></label><label>Password<input type=\"password\" id=\"wpsk\" placeholder=\"empty: keep the stored one\"></label>\n"
    "<label>Country (two letters)<input type=\"text\" id=\"wcc\" maxlength=\"2\" placeholder=\"GB\" style=\"max-width:7em\"></label>\n"
    "<p class=\"mut\" id=\"wapn\" style=\"display:none\">You are on the Pi's own access point, and the radio has only one network at a time: a test join would end it. Save your network, then restart: the Pi joins it at the next start. If the password was wrong, the Mac's screen says so; hold the interrupt button on the recovery screen again to come back here.</p>\n"
    "<div class=\"row\" style=\"margin-top:14px\"><button class=\"b\" id=\"wtest\" onclick=\"wifi('test')\">Test join now</button><button class=\"b p\" id=\"wsave\" onclick=\"wifi('save')\">Save to cmdline.txt</button><button class=\"b p\" id=\"wsj\" style=\"display:none\" onclick=\"wsavejoin()\">Save and restart to join this network</button><span class=\"mut\" id=\"wst\"></span></div></div></section>\n"
    "<section class=\"tab\" id=\"op\"><div class=\"card\"><h2><span>Options</span></h2><p class=\"mut\">Every option you may need, grouped, for the board chosen first: options another board uses are hidden (their values are kept). Changes only the options you edit; every other word in cmdline.txt is kept, and the line before is kept as cmdline.bak. The WiFi network is set on the WiFi tab.</p><div id=\"opts\"></div><p id=\"hidden\"></p>\n"
    "<div class=\"row\" style=\"margin-top:12px\"><button class=\"b\" onclick=\"opts(1)\">Preview the new line</button><button class=\"b p\" onclick=\"opts(0)\">Save</button></div><pre id=\"optline\"></pre></div></section>\n"
    "<section class=\"tab\" id=\"dg\">\n"
    "<div class=\"card\"><h2><span>Run now</span></h2><p class=\"mut\" id=\"dgb\" style=\"margin:0\"></p><ul class=\"ml\" id=\"dgrun\"></ul>\n"
    "<div id=\"dgrep\" style=\"display:none;margin-top:12px\"><div class=\"sug\"><div class=\"verd\" id=\"dgv\"></div><p class=\"mut\" id=\"dgh\"></p><pre id=\"dgl\" style=\"margin:0 0 10px\"></pre>\n"
    "<div class=\"row\"><button class=\"b\" id=\"dgback\" onclick=\"dgback()\">Give the screens back to Setup and Recovery</button></div></div></div></div>\n"
    "<div class=\"card\"><h2><span>Run on the next start</span></h2><p class=\"mut\">A one-shot debug start: the options chosen here go into debug-once.txt on the card. The next start adds them to cmdline.txt's and at once renames the file debug-once.old, so they are used once whatever that start does; the start after it is as cmdline.txt says, and the boot counter counts as always.</p>\n"
    "<div id=\"dgonce\"></div><p class=\"mut\" id=\"oncest\"></p><div class=\"row\"><button class=\"b\" onclick=\"oncearm(0)\">Arm</button><button class=\"b p\" onclick=\"oncearm(1)\">Arm and restart normally</button><button class=\"b d\" onclick=\"oncecancel()\">Cancel</button></div></div>\n"
    "<div class=\"card\"><h2><span>Reports on the card</span></h2><p class=\"mut\" style=\"margin:0\">The Pi has no clock: the kernel's own files carry no time, only their verdict.</p><ul class=\"fl\" id=\"reps\"></ul><pre id=\"repv\" style=\"display:none\"></pre></div>\n"
    "<div class=\"card\"><h2><span>Report bundle</span></h2><p class=\"mut\">One text file with the machine's summary (board, kernel, CPLD, memory, the options in effect), every report above and both logs, to send with an issue. WiFi passwords, tokens and the PIN are replaced by (hidden).</p>\n"
    "<div class=\"row\"><button class=\"b p\" onclick=\"bundle(1)\">Download the bundle</button><button class=\"b\" onclick=\"bundle(0)\">View it here</button></div><pre id=\"bunv\" style=\"display:none\"></pre></div></section>\n"
    "<section class=\"tab\" id=\"dp\">\n"
    "<div class=\"card warn\" id=\"dsaved\" style=\"display:none\"><h2><span>Saved</span></h2><p id=\"dsavedt\" style=\"margin:0 0 8px\"></p><pre id=\"dsavedf\" style=\"margin:0 0 10px\"></pre>\n"
    "<div class=\"row\"><button class=\"b p\" onclick=\"act('/r/reboot?how=normal','Restart the Pi normally (the Mac starts)?')\">Restart normally</button><button class=\"b\" onclick=\"el('dsaved').style.display='none'\">Not now</button></div></div>\n"
    "<div class=\"card\"><h2><span>The HDMI monitor</span></h2><div class=\"grid dg\" id=\"dmon\"></div><p class=\"mut\" id=\"dmonn\" style=\"margin:0\"></p></div>\n"
    "<div class=\"card\" id=\"dsugc\" style=\"display:none\"><h2><span>Suggested</span></h2><div class=\"sug\"><div class=\"big\" id=\"dsug\"></div><p class=\"mut\" id=\"dsugr\"></p>\n"
    "<button class=\"b p\" onclick=\"duse(D.suggested.use)\">Use the suggestion</button></div></div>\n"
    "<div class=\"card\"><h2><span>In force</span></h2><div class=\"grid dg\" id=\"dnow\"></div><div id=\"dnotes\" class=\"mut\" style=\"margin-top:10px\"></div></div>\n"
    "<div class=\"card\"><h2><span>Resolutions</span></h2><p class=\"mut\" id=\"dhead\" style=\"margin:0\"></p>\n"
    "<div class=\"row\" style=\"align-items:flex-end\"><label style=\"flex:1 1 180px\">Turn the picture (clockwise)<select id=\"drot\"><option value=\"0\">0 degrees: upright</option><option value=\"90\">90 degrees</option><option value=\"180\">180 degrees</option><option value=\"270\">270 degrees</option></select></label>\n"
    "<button class=\"b\" onclick=\"drot()\" style=\"margin-bottom:2px\">Save the rotation only</button></div>\n"
    "<label class=\"chk\"><input type=\"checkbox\" id=\"dconf\" checked>Ask on the Mac's screen whether to keep a new mode (without an answer the old one comes back)</label>\n"
    "<ul class=\"ml\" id=\"dmodes\"></ul></div>\n"
    "<div class=\"card\"><h2><span>aurora68-display.txt</span></h2><div class=\"mut\" id=\"dfile\"></div><pre id=\"dtext\"></pre></div></section>\n"
    "<section class=\"tab\" id=\"tx\"><div class=\"card\"><h2><span>cmdline.txt and config.txt</span></h2>\n"
    "<div class=\"row\"><select id=\"tname\" onchange=\"loadtext()\" style=\"max-width:14em\"><option>cmdline.txt</option><option>config.txt</option></select><button class=\"b\" onclick=\"loadtext()\">Reload</button></div>\n"
    "<textarea id=\"text\" style=\"margin-top:10px\"></textarea><p class=\"mut\">Secrets show as ***; saving *** keeps them as they are. The old file is kept as .bak.</p><button class=\"b p\" onclick=\"savetext()\">Save</button></div></section>\n"
    "<section class=\"tab\" id=\"lo\"><div class=\"card\"><h2><span>Logs</span></h2><div class=\"row\"><button class=\"b\" onclick=\"log(0)\">Last start (aurora68.log)</button><button class=\"b\" onclick=\"log(1)\">This recovery start</button></div><pre id=\"log\">Choose a log.</pre></div></section>\n"
    "</main>\n"
    "<div id=\"gate\"><div class=\"card\"><h2><span>Setup and Recovery</span></h2><svg class=\"logo\" viewBox=\"0 0 32 32\" aria-hidden=\"true\"><defs><clipPath id=\"lc\"><rect x=\"1.25\" y=\"1.25\" width=\"29.5\" height=\"29.5\" rx=\"7\"/></clipPath><filter id=\"lb\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feGaussianBlur stdDeviation=\"4.2\"/></filter><filter id=\"lr\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feGaussianBlur stdDeviation=\"1.1\"/></filter><pattern id=\"lp\" width=\"1.9\" height=\"32\" patternUnits=\"userSpaceOnUse\"><rect width=\".8\" height=\"32\" fill=\"#fff\" fill-opacity=\".14\"/></pattern><linearGradient id=\"lf\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\".25\" stop-color=\"#fff\"/><stop offset=\".8\" stop-color=\"#fff\" stop-opacity=\"0\"/></linearGradient><mask id=\"lm\"><rect width=\"32\" height=\"32\" fill=\"url(#lf)\"/></mask></defs><g clip-path=\"url(#lc)\"><rect width=\"32\" height=\"32\" fill=\"#963d97\"/><g filter=\"url(#lb)\"><circle cx=\"4\" cy=\"4\" r=\"9\" fill=\"#61bb46\"/><circle cx=\"20\" cy=\"2\" r=\"8\" fill=\"#fdb827\"/><circle cx=\"31\" cy=\"12\" r=\"8\" fill=\"#f5821f\"/><circle cx=\"26\" cy=\"27\" r=\"9\" fill=\"#e03a3e\"/><circle cx=\"10\" cy=\"31\" r=\"9\" fill=\"#963d97\"/><circle cx=\"1\" cy=\"18\" r=\"8\" fill=\"#009ddc\"/></g><g mask=\"url(#lm)\"><path d=\"M-2 13 C5 7 10 12 16 9 S26 5 34 9 V15 C27 11.5 21 15.5 15 13 S5 12.5 -2 16Z\" fill=\"#fff\" fill-opacity=\".5\" filter=\"url(#lr)\"/><path d=\"M-2 13 C5 7 10 12 16 9 S26 5 34 9 V26 H-2Z\" fill=\"url(#lp)\"/></g></g><rect x=\"1.25\" y=\"1.25\" width=\"29.5\" height=\"29.5\" rx=\"7\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.2\"/></svg><p style=\"margin:8px 0 0\"><b>Enter the PIN</b></p><p class=\"mut\">The four digits on the Mac's screen (or on HDMI).</p>\n"
    "<input id=\"pin\" inputmode=\"numeric\" maxlength=\"4\" autocomplete=\"off\" onkeydown=\"if(event.key=='Enter')savepin()\"><button class=\"b p\" style=\"width:100%\" onclick=\"savepin()\">Continue</button></div></div>\n"
    "<div id=\"toast\"></div>\n"
    "<script>\n"
    "var P=sessionStorage.getItem('pin')||'',T=null,loaded={},AP=null;\n"
    "function el(i){return document.getElementById(i)}\n"
    "function toast(t,bad){var x=el('toast');x.textContent=t;x.className='on'+(bad?' bad':'');clearTimeout(T);T=setTimeout(function(){x.className=''},3200)}\n"
    "function msg(t){if(t)toast(t,1)}\n"
    "function lock(){el('gate').style.display='flex';el('pin').value='';el('pin').focus()}\n"
    "function savepin(){P=el('pin').value.trim();sessionStorage.setItem('pin',P);el('gate').style.display='none';refresh()}\n"
    "function api(m,u,b,raw){var o={method:m,headers:{'X-Aurora-Pin':P}};if(b!==undefined)o.body=b;return fetch(u,o).then(function(r){\n"
    " if(r.status==401){toast('PIN wrong or missing',1);lock();throw 0}if(r.status==429){toast('Too many wrong PINs: wait a minute and use the new one',1);lock();throw 0}\n"
    " if(raw)return r;return r.json().then(function(x){if(!r.ok){toast(x.error||('error '+r.status),1);throw 0}return x})})}\n"
    "function esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return'&#'+c.charCodeAt(0)+';'})}\n"
    "function kb(n){return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}\n"
    "function act(u,q){if(q&&!confirm(q))return;api('POST',u).then(function(x){toast(x.note||'Done');refresh()},function(){})}\n"
    "function show(t){if(t!='dg')dgstop();[].forEach.call(document.querySelectorAll('nav button'),function(b){b.className=b.dataset.t==t?'on':''});\n"
    " [].forEach.call(document.querySelectorAll('.tab'),function(s){s.className='tab'+(s.id==t?' on':'')});\n"
    " if(t=='fi')files();if(t=='wi')wifiget();if(t=='op')opts(-1);if(t=='dp')dget();if(t=='dg')dgget(1);if(t=='tx'&&!loaded.tx){loaded.tx=1;loadtext()}var nb=document.querySelector('nav button.on');if(nb&&nb.scrollIntoView)nb.scrollIntoView({block:'nearest',inline:'nearest'});history.replaceState(null,'','#'+t);window.scrollTo(0,0)}\n"
    "el('nav').onclick=function(e){if(e.target.dataset.t)show(e.target.dataset.t)};\n"
    "function kv(k,v){return'<div class=\"kv\"><b>'+k+'</b><span>'+v+'</span></div>'}\n"
    "function refresh(){api('GET','/r/state').then(function(s){el('why').textContent=s.why;el('rb').style.display=s.rollback_offered?'':'none';var n=s.network;\n"
    " el('hstate').textContent=(n.ip||n.phase)+(n.name?'  \302\267  '+n.name:'');\n"
    " el('st').innerHTML=kv('Network',esc(n.link)+' '+esc(n.ip)+' <span class=\"pill\">'+esc(n.phase)+'</span>')+kv('WiFi',n.wifi?esc(n.wifi.state)+' '+esc(n.wifi.ssid):'off')+\n"
    "  kv('Card',esc(s.card))+kv('Upload',esc(s.upload.state)+(s.upload.total?' '+esc(s.upload.name)+' '+kb(s.upload.received)+' of '+kb(s.upload.total):''))+kv('Last action',esc(s.last));\n"
    " el('notes').innerHTML=(s.cmdline_recovery?'cmdline.txt has <b>mac.recovery=1</b> or <b>recovery.ap</b>: \"Restart normally\" takes it out. ':'')+(s.config_kernel?'config.txt starts <b>'+esc(s.config_kernel)+'</b>, not kernel8.img.':'');\n"
    " var o=s.once||{};el('oncec').style.display=o.armed?'':'none';if(o.armed)el('oncet').innerHTML='The next start adds <b>'+esc(o.words)+'</b> to cmdline.txt\\'s options, once (debug-once.txt). The start after it is normal again.';\n"
    " var a=AP=s.ap;el('apc').style.display=a?'':'none';\n"
    " if(a&&a.state=='up'&&!sessionStorage.getItem('apin')){sessionStorage.setItem('apin','1');location.replace('/');return}\n"
    " if(a){el('apg').innerHTML=kv('Network',esc(a.ssid||'(starting)'))+kv('State',esc(a.detail)+(a.error?': '+esc(a.error):''))+(a.state=='up'?kv('Security',esc(a.security))+kv('Address',esc(a.address))+kv('Devices',esc(a.clients)+' with an address'):'');\n"
    "  el('apn').innerHTML=a.state=='up'?'The Pi is running a WiFi network of its own for setup ('+esc(a.how)+'). Put your home network in on the <a href=\"#wi\" onclick=\"show(\\'wi\\');return false\">WiFi</a> tab and choose <b>Save and restart to join this network</b>. The access point is never kept: the next start joins the saved network.':\n"
    "   a.state=='failed'?'The access point did not start. The Pi carries on with the wired port or the saved WiFi; the Mac\\'s screen and the log say what the WiFi chip answered.':'Starting the access point...'}\n"
    " var t=(location.hash||'#ov').slice(1);show(el(t)?t:'ov')},function(){})}\n"
    "function files(){api('GET','/r/files').then(function(x){el('card').textContent=x.card+(x.free_kb!==undefined?', '+kb(x.free_kb*1024)+' free':'');\n"
    " var h='';x.files.forEach(function(f){if(f.folder){h+='<li><span class=\"nm\">'+esc(f.name)+'/</span></li>';return}\n"
    " var a=esc(f.name).replace(/&#39;/g,\"\\\\'\");h+='<li><span class=\"nm\">'+esc(f.name)+'</span><span class=\"sz\">'+kb(f.size)+'</span><span class=\"ac\"><button class=\"b s\" onclick=\"dl(\\''+a+'\\')\">Get</button><button class=\"b s\" onclick=\"mv(\\''+a+'\\')\">Rename</button>'+\n"
    " (f.name.toLowerCase()=='kernel8.img'?'':'<button class=\"b s d\" onclick=\"rm(\\''+a+'\\')\">Delete</button>')+'</span></li>'});el('files').innerHTML=h},function(){})}\n"
    "function dl(n){api('GET','/r/file?name='+encodeURIComponent(n),undefined,1).then(function(r){return r.blob()}).then(function(b){var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=n;document.body.appendChild(a);a.click();a.remove()})}\n"
    "function rm(n){act('/r/rm?name='+encodeURIComponent(n),'Delete '+n+'?')}\n"
    "function mv(n){var t=prompt('New name for '+n,n);if(t&&t!=n)act('/r/mv?from='+encodeURIComponent(n)+'&to='+encodeURIComponent(t))}\n"
    "function upload(){var f=el('up').files[0];if(!f){toast('Choose a file first',1);return}var n=el('upname').value.trim()||f.name;var x=new XMLHttpRequest();\n"
    " x.open('PUT','/r/file?name='+encodeURIComponent(n));x.setRequestHeader('X-Aurora-Pin',P);\n"
    " x.upload.onprogress=function(e){el('upst').textContent=kb(e.loaded)+' of '+kb(e.total);el('upbar').style.width=(100*e.loaded/e.total)+'%'};\n"
    " x.onload=function(){var j={};try{j=JSON.parse(x.responseText)}catch(e){}if(x.status==200){el('upst').textContent='Done: '+n+' '+kb(j.size)+', CRC32 '+j.crc32+(j.check?' ('+j.check+')':'');toast('Uploaded '+n)}\n"
    "  else{el('upst').textContent='Refused: '+(j.error||x.status);toast('Refused: '+(j.error||x.status),1)}el('upbar').style.width='0';files();refresh()};\n"
    " x.onerror=function(){el('upst').textContent='The connection broke';toast('The connection broke',1)};el('upst').textContent='Sending...';x.send(f)}\n"
    "function wifiget(){var ap=AP&&AP.state!='failed';el('wtest').style.display=ap?'none':'';el('wsave').style.display=ap?'none':'';el('wsj').style.display=ap?'':'none';el('wapn').style.display=ap?'':'none';\n"
    " api('GET','/r/wifi').then(function(w){var s=w.settings;el('wset').textContent='cmdline.txt: '+(s.ssid||'(no network)')+', password '+s.psk+', country '+(s.country||'(default)')+\n"
    " (w.radio?'. Radio: '+w.radio.state+' '+w.radio.message:'. No WiFi radio')+(w.note?'. Test: '+w.note:'');if(!el('wssid').value)el('wssid').value=s.ssid;if(!el('wcc').value)el('wcc').value=s.country;\n"
    " var h='<option value=\"\">(choose from the scan)</option>';w.scan.forEach(function(n){h+='<option value=\"'+esc(n.ssid)+'\">'+esc(n.ssid)+'  '+n.rssi+' dBm  '+n.security+'</option>'});el('wlist').innerHTML=h},function(){})}\n"
    "function wscan(){api('POST','/r/wifi/scan').then(function(){toast('Scanning...');setTimeout(wifiget,3000)},function(){})}\n"
    "function wbody(){return 'ssid='+encodeURIComponent(el('wssid').value)+'&psk='+encodeURIComponent(el('wpsk').value)+'&country='+encodeURIComponent(el('wcc').value.toUpperCase())}\n"
    "function wsavejoin(){var n=el('wssid').value;if(!n){toast('Type the network name first',1);return}if(!confirm('Save '+n+' and restart the Pi to join it? This access point closes.'))return;\n"
    " api('POST','/r/wifi/save',wbody()).then(function(){return api('POST','/r/reboot?how=normal')}).then(function(){el('wst').textContent='Saved; the Pi restarts and joins '+n;toast('Saved. The Pi restarts and joins '+n)},function(){})}\n"
    "function wifi(w){var b=wbody();\n"
    " if(w=='save'&&el('wst').textContent.indexOf('joined')<0&&!confirm('The new settings have not joined in a test. Save them anyway?'))return;\n"
    " api('POST','/r/wifi/'+w,b).then(function(){el('wst').textContent=w=='test'?'Testing...':'Saved';if(w=='test')wpoll(0);else toast('Saved to cmdline.txt')},function(){})}\n"
    "function wpoll(i){api('GET','/r/wifi').then(function(w){if(w.test=='running'&&i<30)setTimeout(function(){wpoll(i+1)},1500);else el('wst').textContent=w.note||w.test||'No answer';wifiget()},function(){})}\n"
    "// the Options tab (docs/08 item 120): the kernel's table of options (GET /r/options: defs, groups), each with the boards that\n"
    "// use it; the board chosen hides the others' options (their values are kept)\n"
    "var DEF=null,OG=[],OV={};\n"
    "function optfield(o,v){var id='o_'+o.key;\n"
    " if(o.secret)return'<input type=\"password\" id=\"'+id+'\" placeholder=\"'+(v?'(set: type to change)':'(not set)')+'\">';\n"
    " if(o.menu){var vs=[''].concat(o.values.split('|'));return'<select id=\"'+id+'\">'+vs.map(function(c){return'<option'+(c==v?' selected':'')+' value=\"'+esc(c)+'\">'+(c||'(not given)')+'</option>'}).join('')+\n"
    "  (v&&vs.indexOf(v)<0?'<option selected value=\"'+esc(v)+'\">'+esc(v)+' (not a value it takes)</option>':'')+'</select>'}\n"
    " return'<input type=\"text\" id=\"'+id+'\" value=\"'+esc(v)+'\" placeholder=\"'+esc(o.example||'')+'\">'}\n"
    "function boardfilter(){var f=el('o_mac.board');if(!f||!DEF)return;var bd=f.value||'iici',n=0,sh={},un=[];\n"
    " DEF.forEach(function(o){var d=el('d_'+o.key);if(!d)return;var on=o.boards.split(' ').indexOf(bd)>=0;d.style.display=on?'':'none';if(on)sh[o.group]=1;else{n++;if(OV[o.key]!=null)un.push(o.key)}});\n"
    " OG.forEach(function(g,i){var x=el('g_'+i);if(x)x.style.display=sh[i]?'':'none'});\n"
    " el('hidden').textContent=(n?n+' option'+(n>1?'s':'')+' hidden: not used on '+(bd=='solo'?'the bench (no Mac)':bd=='iici'?'the testbed\\'s IIci':'this board')+'; their values are kept.':'')+(un.length?' Set but not used on it: '+un.join(', ')+'.':'')}\n"
    "function opts(dry){if(dry<0){api('GET','/r/options').then(function(x){DEF=x.defs;OG=x.groups;OV=x.values;var h='';\n"
    " OG.forEach(function(g,gi){var hh='',any=0;DEF.forEach(function(o){if(o.group!=gi||o.wifitab)return;any=1;var v=OV[o.key];if(v==null)v='';\n"
    "  hh+='<div class=\"opt\" id=\"d_'+o.key+'\"><code>'+esc(o.key)+'</code><p>'+esc(o.text)+'</p>'+optfield(o,v)+'</div>'});if(any)h+='<div class=\"og\" id=\"g_'+gi+'\">'+esc(g)+'</div>'+hh});\n"
    " el('opts').innerHTML=h;el('optline').textContent=x.line;el('o_mac.board').onchange=boardfilter;boardfilter()},function(){});return}\n"
    " var e=[];DEF.forEach(function(o){var f=el('o_'+o.key);if(!f||o.wifitab)return;var v=f.value.trim(),old=OV[o.key]==null?'':OV[o.key];if(o.secret){if(v)e.push(o.key+'='+v);return}if(v!=old)e.push(v?o.key+'='+v:'-'+o.key)});\n"
    " api('POST','/r/options'+(dry?'?dry=1':''),e.join('\\n')).then(function(x){el('optline').textContent=(dry?'The new line would be:\\n':'Saved (the line before is in cmdline.bak):\\n')+x.line;if(!dry){toast('Options saved');opts(-1)}},function(){})}\n"
    "// the Diagnostics tab (docs/08 item 120): GET /r/diag (the bus check's lines from ?from=N as they come), POST /r/diag/run?test=,\n"
    "// /r/diag/screen, /r/diag/once; GET /r/reports, /r/bundle\n"
    "var G=null,GL=[],GT=null;\n"
    "function dgstop(){if(GT){clearTimeout(GT);GT=null}}\n"
    "function dgdefs(){return DEF?Promise.resolve():api('GET','/r/options').then(function(x){DEF=x.defs;OG=x.groups;OV=x.values})}\n"
    "function dgget(first){dgstop();if(first){GL=[];el('repv').style.display='none'}api('GET','/r/diag?from='+GL.length).then(function(g){G=g;GL=GL.concat(g.buscheck.lines);dgrender(first);\n"
    " var run=g.buscheck.state=='asked'||g.buscheck.state=='running'||g.cardtest.state=='running'||g.jtag.again=='reading';if(run)GT=setTimeout(function(){dgget(0)},700);else if(!first&&(dgget.was))reports();dgget.was=run},function(){})}\n"
    "function dgrow(t,d,btn,dim){return'<li'+(dim?' class=\"dim\"':'')+'><span class=\"sz\">'+t+'</span><span class=\"dt\">'+d+'</span><span class=\"ac\">'+btn+'</span></li>'}\n"
    "function dgrender(first){var g=G,b=g.buscheck,c=g.cardtest,j=g.jtag,h='';\n"
    " el('dgb').textContent='This is '+g.board_name+'. The Mac is not running, so these checks have the board to themselves.';\n"
    " var busy=b.state=='asked'||b.state=='running';\n"
    " h+=dgrow('Bus check',b.refusal?'Not here: '+esc(b.refusal)+'.'+(b.force_runs?' <button class=\"b s\" onclick=\"dgrun(\\'buscheck\\',1)\">Run over the bridge (testbed)</button>':''):\n"
    "  'The bus between the Pi and the logic board: the RAM\\'s address and data lines (and how much RAM answers), the VIA and the SCC, the ROM, every access\\'s time, what a retry would cure, reads during the picture. A few seconds on a PiStorm; the report shows here, on the Mac\\'s own screen and on HDMI.'+(busy?' <span class=\"pill k\">running</span>':''),\n"
    "  b.refusal?'':'<button class=\"b s p\" onclick=\"dgrun(\\'buscheck\\',0)\"'+(busy?' disabled':'')+'>Run</button>',!!b.refusal);\n"
    " h+=dgrow('Card read test','Reads the largest file on the card (16 MB at most) as the disk images are read, and gives the speed and any read error'+(c.state=='running'?': '+kb(c.got)+' of '+kb(c.total)+' of '+esc(c.file):'')+'.'+(c.state=='done'?' <b>'+esc(c.verdict)+'.</b>':''),\n"
    "  '<button class=\"b s\" onclick=\"dgrun(\\'card\\')\"'+(c.state=='running'?' disabled':'')+'>Run</button>');\n"
    " var jt=j.at_start?'Read at this start: '+esc(j.at_start.usercode)+', '+esc(j.at_start.name)+'.':'';if(j.again=='read')jt+=' Read again: <b>'+esc(j.usercode)+'</b>, '+esc(j.name)+'.';else if(j.again=='failed')jt+=' Read again: the read failed.';\n"
    " h+=dgrow('CPLD usercode',j.refusal?'Not here: '+esc(j.refusal)+'.':'Which PiStorm firmware the CPLD carries (its JTAG usercode). '+jt,j.refusal?'':'<button class=\"b s\" onclick=\"dgrun(\\'jtag\\')\">Read again</button>',!!j.refusal);\n"
    " h+=dgrow('HDMI monitor','Its description (EDID), read at this start, and the modes the Pi can send: on the <a href=\"#dp\" onclick=\"show(\\'dp\\');return false\">Display</a> tab.','');\n"
    " el('dgrun').innerHTML=h;\n"
    " var r=el('dgrep');r.style.display=GL.length?'':'none';el('dgl').textContent=GL.join('\\n');\n"
    " el('dgv').textContent=b.state=='done'?'Bus check: '+b.verdict:busy?'Bus check running...':'';\n"
    " el('dgh').textContent=b.state=='done'?b.headline+(b.file>0?' The report is in buscheck.txt.':b.file<0?' (buscheck.txt could not be written: the card is read only.)':''):'';\n"
    " el('dgback').style.display=b.screen=='report'?'':'none';\n"
    " dgonce(g.once,first);if(first)reports()}\n"
    "function dgrun(t,f){api('POST','/r/diag/run?test='+t+(f?'&force=1':'')).then(function(){if(t=='buscheck')GL=[];toast(t=='buscheck'?'The bus check is running':t=='card'?'Reading the card':'Reading the CPLD');dgget(0)},function(){})}\n"
    "function dgback(){api('POST','/r/diag/screen').then(function(){toast('The screens are Setup and Recovery\\'s again');dgget(0)},function(){})}\n"
    "function dgonce(o,first){dgdefs().then(function(){var bd=G.board,h='',w={};(o.words||'').split(' ').forEach(function(x){var i=x.indexOf('=');if(i>0)w[x.slice(0,i)]=x.slice(i+1)});\n"
    " if(first||!el('dgonce').innerHTML){DEF.forEach(function(d){if(!d.once||d.boards.split(' ').indexOf(bd)<0)return;var v=w[d.key]!=null?w[d.key]:d.menu?d.values.split('|')[0]:(d.example||'');\n"
    "  var f=d.menu?'<select id=\"u_'+d.key+'\">'+d.values.split('|').map(function(c){return'<option'+(c==v?' selected':'')+'>'+esc(c)+'</option>'}).join('')+'</select>':'<input type=\"text\" id=\"u_'+d.key+'\" value=\"'+esc(v)+'\" placeholder=\"'+esc(d.example)+'\">';\n"
    "  h+='<label class=\"chk2\"><input type=\"checkbox\" id=\"k_'+d.key+'\"'+(w[d.key]!=null?' checked':'')+'><span class=\"ov\"><code>'+esc(d.key)+'</code><p>'+esc(d.text)+'</p>'+f+'</span></label>'});el('dgonce').innerHTML=h}\n"
    " el('oncest').innerHTML=(o.armed?'Armed for the next start: <b>'+esc(o.words)+'</b>.':'Nothing armed.')+(o.used_now?' This start used: '+esc(o.used_now)+'.':'')+(o.last?' The last one used: '+esc(o.last)+' (debug-once.old).':'')})}\n"
    "function oncearm(rs){var e=[];DEF.forEach(function(d){var k=el('k_'+d.key);if(k&&k.checked)e.push(d.key+'='+el('u_'+d.key).value.trim())});if(!e.length){toast('Tick at least one option',1);return}\n"
    " if(rs&&!confirm('Arm '+e.join(' ')+' and restart the Pi normally? It is used once.'))return;\n"
    " api('POST','/r/diag/once',e.join(' ')).then(function(x){toast('Armed: '+x.words);if(rs)return api('POST','/r/reboot?how=normal').then(function(){toast('The Pi restarts with the debug options, once')});dgget(1);refresh()},function(){})}\n"
    "function oncecancel(){api('POST','/r/diag/once?cancel=1').then(function(x){toast(x.note);if(el('dg').className.indexOf('on')>=0)dgget(1);refresh()},function(){})}\n"
    "function reports(){api('GET','/r/reports').then(function(x){var h='';x.reports.forEach(function(f){var a=esc(f.name).replace(/&#39;/g,\"\\\\'\");\n"
    " h+='<li><span class=\"nm\">'+esc(f.name)+(f.this_start?' <span class=\"pill k\">this start</span>':'')+'<br><span class=\"mut\" style=\"font-family:var(--ui)\">'+esc(f.what)+(f.verdict?': <b>'+esc(f.verdict)+'</b>':'')+'</span></span><span class=\"sz\">'+kb(f.size)+(f.time?'<br>'+esc(f.time):'')+\n"
    "  '</span><span class=\"ac\"><button class=\"b s\" onclick=\"repview(\\''+a+'\\')\">View</button><button class=\"b s\" onclick=\"dl(\\''+a+'\\')\">Get</button></span></li>'});el('reps').innerHTML=h||'<li>No reports on the card yet.</li>'},function(){})}\n"
    "function repview(n){var v=el('repv');v.style.display='';v.textContent='Loading '+n+'...';api('GET','/r/file?name='+encodeURIComponent(n),undefined,1).then(function(r){return r.text()}).then(function(t){v.textContent=t;v.scrollIntoView&&v.scrollIntoView({block:'nearest'})})}\n"
    "function bundle(d){api('GET','/r/bundle',undefined,1).then(function(r){return d?r.blob():r.text()}).then(function(x){if(!d){var v=el('bunv');v.style.display='';v.textContent=x;return}\n"
    " var a=document.createElement('a');a.href=URL.createObjectURL(x);a.download='aurora68-report.txt';document.body.appendChild(a);a.click();a.remove();toast('aurora68-report.txt')})}\n"
    "function loadtext(){var n=el('tname').value;api('GET','/r/text?name='+n,undefined,1).then(function(r){return r.text()}).then(function(t){el('text').value=t})}\n"
    "function savetext(){var n=el('tname').value;if(!confirm('Write '+n+'?'))return;api('PUT','/r/text?name='+n,el('text').value).then(function(x){toast('Saved '+x.saved+', the old one as '+x.backup);refresh()},function(){})}\n"
    "function log(now){el('log').textContent='Loading...';api('GET','/r/log'+(now?'?now=1':''),undefined,1).then(function(r){return r.text()}).then(function(t){el('log').textContent=t||'(empty)'})}\n"
    "// the Display tab (docs/08 item 111): GET /r/display, and POST /r/display with the mode, the rotation and the include line\n"
    "var D=null;\n"
    "function dhz(x){return x==null?'?':Math.round(x*100)%100?x.toFixed(2):String(Math.round(x))}\n"
    "function dsz(w,h){return w+' x '+h}\n"
    "function dget(){api('GET','/r/display').then(function(d){D=d;drender()},function(){})}\n"
    "function drender(){var d=D,m=d.monitor,h='',n=d.now,f=d.file;\n"
    " if(m){var mm=m.size_mm;h=kv('Name',esc(m.name||'(not given)'))+kv('Maker',esc(m.maker_name?m.maker_name+' ('+m.maker+')':m.maker))+kv('Model','product code '+esc(m.product))+\n"
    "  kv('Serial number',esc(m.serial||'not given')+' <span class=\"pill\">shortened</span>')+kv('Made',m.week&&m.week<54?'week '+m.week+' of '+m.year:esc(m.year))+\n"
    "  kv('Picture',mm[0]?(mm[0]/10).toFixed(1)+' x '+(mm[1]/10).toFixed(1)+' cm, '+m.size_in.w+' x '+m.size_in.h+' in, '+m.size_in.diagonal+'\" diagonal':'not given')+\n"
    "  kv('Panel',m.native?esc(m.native.replace('x',' x '))+' pixels, '+esc(m.shape):'?')+kv('Connection',esc(m.connection)+'; sound: '+esc(m.sound))+\n"
    "  kv('Pixel clock','the Pi 3 sends up to '+d.pi_mhz.toFixed(0)+' MHz'+(m.max_mhz?'; the monitor takes '+m.max_mhz.toFixed(0):''))+\n"
    "  kv('Description','EDID '+esc(m.edid_version)+', '+m.blocks+' block'+(m.blocks==1?'':'s')+(m.checksum_ok?'':' (a checksum is wrong)')+(m.sample?' <span class=\"pill\">the testbed\\'s sample</span>':''));\n"
    "  el('dmonn').textContent=''}\n"
    " else el('dmonn').textContent=(d.edid_status=='header'?'The monitor\\'s description (EDID) could not be read.':'No description (EDID) came from a monitor: none is connected, or the firmware gave none (QEMU has no monitor; mac.edidtest=sample gives it one).')+\n"
    "  ' The standard modes below can still be chosen, and Automatic lets the firmware ask the monitor at the next start.';\n"
    " el('dmon').innerHTML=h;el('dmon').style.display=h?'':'none';\n"
    " var s=d.suggested;el('dsugc').style.display=s?'':'none';\n"
    " if(s){el('dsug').textContent=dsz(s.w,s.h)+' at '+dhz(s.hz)+' Hz';el('dsugr').textContent=s.reason+'.'}\n"
    " var nx=f.next,rs=n.rotation!=f.rotation;\n"
    " el('dnow').innerHTML=kv('HDMI now',dsz(n.w,n.h)+(n.hz?' at '+dhz(n.hz)+' Hz':'')+(n.rotation?', turned '+n.rotation+'&deg;':''))+kv('Set by',n.source.indexOf('firmware')>=0?'the firmware\\'s own choice (no hdmi_mode)':esc(n.source)+': '+esc(n.text))+\n"
    "  kv('From the next start',f.present?(nx.w?dsz(nx.w,nx.h)+(nx.hz?' at '+dhz(nx.hz)+' Hz':''):esc(nx.text))+(f.rotation||rs?', turned '+f.rotation+'&deg;':'')+(f.confirm?' <span class=\"pill\">to be kept on the Mac</span>':''):'no aurora68-display.txt yet: config.txt\\'s own lines')+\n"
    "  kv('config.txt',!d.config.read?'not on the card':d.config.include?(d.config.override?'includes the file, but an hdmi_ line after it wins':'includes aurora68-display.txt at its end'):'no include line')+\n"
    "  kv('mac.screen',d.cmdline.mac_screen?esc(d.cmdline.mac_screen)+' (cmdline.txt)':'not set: the Mac\\'s screen is the mode\\'s size');\n"
    " var t='';\n"
    " if(d.config.read&&!d.config.include)t+='<p><b>config.txt has no line \"include aurora68-display.txt\"</b>, so the firmware would not read the mode chosen here. <button class=\"b s\" onclick=\"dinc()\">Add it at the end of config.txt</button></p>';\n"
    " else if(d.config.override)t+='<p><b>config.txt sets an hdmi_ mode after its include line</b>, which wins. <button class=\"b s\" onclick=\"dinc()\">Move the line to the end</button></p>';\n"
    " if(!d.writable)t+='<p><b>The card cannot be written</b>: the modes can be looked at but not chosen.</p>';\n"
    " if(n.confirm_pending)t+='<p>The mode in force waits to be kept: the next normal start asks on the Mac\\'s screen.</p>';\n"
    " el('dnotes').innerHTML=t;\n"
    " el('dhead').textContent=(d.standard?'The standard modes (no monitor description)':'What the monitor lists')+', judged against the Pi 3\\'s '+d.pi_mhz.toFixed(0)+' MHz. Dimmed: the Pi 3 cannot send it.';\n"
    " el('drot').value=String(f.rotation);\n"
    " var L='<li'+(f.present&&nx.text.indexOf('hdmi_group=0')==0?' class=\"sel\"':'')+'><span class=\"sz\">Automatic</span><span class=\"dt\">the monitor\\'s preferred mode, chosen by the firmware at the start'+\n"
    "  (d.preferred?' ('+dsz(d.preferred.w,d.preferred.h)+' at '+dhz(d.preferred.hz)+' Hz)':'')+'</span><span class=\"ac\"><button class=\"b s\" onclick=\"duse(\\'auto\\')\"'+(d.writable?'':' disabled')+'>Use</button></span></li>';\n"
    " d.modes.forEach(function(x){var tg='',dt='';\n"
    "  if(x.suggested)tg+=' <span class=\"pill k\">suggested</span>';if(x.current)tg+=' <span class=\"pill\">in force</span>';if(x.preferred)tg+=' <span class=\"pill\">preferred</span>';\n"
    "  if(x.native&&!x.preferred)tg+=' <span class=\"pill\">the panel\\'s own</span>';if(x.shape)tg+=' <span class=\"pill\">stretched</span>';\n"
    "  if(x.verdict=='usable')dt=dhz(x.hz)+' Hz, '+x.mhz.toFixed(2)+' MHz';\n"
    "  else if(x.verdict=='alternative')dt='<span class=\"gone\">'+dhz(x.hz)+' Hz needs '+x.mhz.toFixed(2)+' MHz</span>: too fast for the Pi 3; '+dhz(x.alt_hz)+' Hz with reduced blanking ('+x.alt_mhz.toFixed(2)+' MHz) fits';\n"
    "  else if(x.verdict=='too_fast')dt=dhz(x.hz)+' Hz needs '+x.mhz.toFixed(2)+' MHz: too fast for the Pi 3, and nothing slower fits';\n"
    "  else dt=dhz(x.hz)+' Hz: '+(x.verdict=='interlaced'?'interlaced, not for the Mac':'outside the sizes the Mac takes');\n"
    "  L+='<li'+(x.choose?'':' class=\"dim\"')+'><span class=\"sz\">'+dsz(x.w,x.h)+'</span><span class=\"dt\">'+dt+tg+'</span><span class=\"ac\">'+\n"
    "   (x.choose?'<button class=\"b s'+(x.suggested?' p':'')+'\" onclick=\"duse(\\''+x.use+'\\')\"'+(d.writable?'':' disabled')+'>Use'+(x.verdict=='alternative'?' '+dhz(x.alt_hz)+' Hz':'')+'</button>':'')+'</span></li>'});\n"
    " el('dmodes').innerHTML=L;\n"
    " el('dfile').textContent=f.present?'On the card now'+(f.bak?'; the one before is aurora68-display.bak':'')+'.':'Not on the card yet: the first choice makes it.';\n"
    " el('dtext').textContent=f.present?f.text:'';el('dtext').style.display=f.present?'':'none'}\n"
    "function dask(what,u){var q=what,inc=0,ms=D.cmdline.mac_screen;\n"
    " if(u&&D.config.read&&(!D.config.include||D.config.override)){q+='\\n\\nconfig.txt '+(D.config.include?'sets an hdmi_ mode after its include line: the line is moved to its end':'has no line \"include aurora68-display.txt\": it is added at its end')+' (config.bak keeps the old one).';inc=1}\n"
    " if(u&&ms&&(u=='auto'||ms!=u.split('@')[0]))q+='\\n\\ncmdline.txt\\'s mac.screen='+ms+(u=='auto'?' is taken out (the firmware chooses the size)':' becomes '+u.split('@')[0])+' (cmdline.bak keeps the line).';\n"
    " return confirm(q+'\\n\\nIt is used from the next start.')?(inc?'&include=1':''):null}\n"
    "function duse(u){var ro=el('drot').value,c=el('dconf').checked?1:0;\n"
    " var x=dask('Use '+(u=='auto'?'Automatic, the firmware\\'s choice from the monitor':u.replace('x',' x ').replace('@',' at ')+' Hz')+(ro!='0'?', turned '+ro+' degrees':'')+'?',u);if(x==null)return;\n"
    " api('POST','/r/display','mode='+encodeURIComponent(u)+'&rotation='+ro+'&confirm='+c+x).then(dsaved,function(){})}\n"
    "function drot(){var ro=el('drot').value;if(dask('Keep the rotation '+ro+' degrees for the HDMI screen?')==null)return;api('POST','/r/display','rotation='+ro).then(dsaved,function(){})}\n"
    "function dinc(){if(!confirm('Put the line \"include aurora68-display.txt\" at the end of config.txt? config.bak keeps the old one.'))return;\n"
    " api('POST','/r/display','include=1').then(function(x){toast('config.txt: the include line '+x.include);dget()},function(){})}\n"
    "function dsaved(x){el('dsaved').style.display='';\n"
    " el('dsavedt').textContent=(x.mode?(x.mode=='auto'?'Automatic':x.mode.replace('x',' x ').replace('@',' at ')+' Hz')+', turned '+x.rotation+' degrees. ':'')+\n"
    "  'aurora68-display.txt holds it now; the one before is aurora68-display.bak.'+(x.include=='added'?' The include line was added to config.txt.':x.include=='moved'?' The include line was moved to the end of config.txt.':'')+\n"
    "  (x.mac_screen?' '+x.mac_screen+'.':'')+' '+x.note;\n"
    " el('dsavedf').textContent=x.text||'';toast('Saved');window.scrollTo(0,0);dget()}\n"
    "if(location.hash.indexOf('#pin=')==0){P=location.hash.slice(5);sessionStorage.setItem('pin',P);history.replaceState(null,'',location.pathname)}\n"
    "if(P)refresh();else lock();\n"
    "</script></body></html>\n";
